(()=>{'use strict';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)],reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
$$('[data-year]').forEach(e=>e.textContent=new Date().getFullYear());
const menu=$('#menu-dialog'),menuBtn=$('.menu-button');menuBtn?.addEventListener('click',()=>{menu.showModal();menuBtn.setAttribute('aria-expanded','true')});$('.close-menu')?.addEventListener('click',()=>menu.close());menu?.addEventListener('close',()=>menuBtn.setAttribute('aria-expanded','false'));
const progress=$('.scroll-progress');addEventListener('scroll',()=>{const d=document.documentElement;progress.style.width=(d.scrollHeight>d.clientHeight?d.scrollTop/(d.scrollHeight-d.clientHeight)*100:0)+'%'},{passive:true});
if(!reduced&&'IntersectionObserver'in window){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.06});$$('.reveal').forEach(e=>observer.observe(e))}
// Every image opens its source-resolution image, including the original floor plans.
const lightbox=$('#lightbox');let lightboxOpener=null;function showImage(src,alt,opener){lightboxOpener=opener;const im=$('img',lightbox);im.src=src;im.alt=alt||'Jewel Homes image';$('p',lightbox).textContent=alt||'';lightbox.showModal()}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const h=a.getAttribute('href')||'';if(a.hasAttribute('data-lightbox')||/\.(?:jpg|jpeg|png|webp)(?:\?.*)?$/i.test(h)){e.preventDefault();showImage(h,$('img',a)?.alt||a.textContent.trim(),a)}});$('.lightbox-close')?.addEventListener('click',()=>lightbox.close());lightbox?.addEventListener('click',e=>{if(e.target===lightbox){const r=lightbox.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)lightbox.close()}});lightbox?.addEventListener('close',()=>lightboxOpener?.focus?.());
// Hero uses Jewel's actual project elevations.
if($('.hero')){fetch('hero-data.json').then(r=>r.json()).then(data=>{let index=0;const slides=$$('.hero-slide');function slide(next){index=(next+data.length)%data.length;slides.forEach((s,i)=>s.classList.toggle('active',i===index));$('#hero-project-name').textContent=data[index].name;$('#hero-project-link').href=data[index].route;$('#hero-project-location').textContent=data[index].facts.find(f=>f.startsWith('Location:'))?.split(':').slice(1).join(':').trim()||'Kerala';$('#hero-index').textContent=String(index+1).padStart(2,'0');$('.hero-track i').style.transform=`translateX(${index*100}%)`};$('.hero-next').addEventListener('click',()=>slide(index+1));$('.hero-prev').addEventListener('click',()=>slide(index-1));if(!reduced){const timer=setInterval(()=>{if(!document.hidden&&!menu.open)slide(index+1)},9000);addEventListener('pagehide',()=>clearInterval(timer),{once:true})}}).catch(()=>{})}
// Directory filters work with searches from the home page too.
const cards=$$('.directory-grid .property-card'),search=$('#project-search'),locationFilter=$('#location-filter');if(cards.length){const params=new URLSearchParams(location.search);let status=params.get('status')||'';if(locationFilter&&params.get('location'))locationFilter.value=params.get('location').toLowerCase();function filter(){let n=0;const query=(search?.value||'').trim().toLowerCase(),loc=locationFilter?.value||'';cards.forEach(c=>{let place=c.dataset.location.toLowerCase();const locationMatch=!loc||(loc==='cochin'?/cochin|kochi|kakkanad|kalamassery|kaloor|palarivattom|vazhakkala|aluva|alwaye/.test(place):place.includes(loc));const match=locationMatch&&(!status||c.dataset.category===status)&&(!query||(c.dataset.name+' '+place).toLowerCase().includes(query));c.hidden=!match;if(match)n++});$('#project-count').textContent=`${n} residence${n===1?'':'s'}`;$('.no-results').hidden=n>0}search?.addEventListener('input',filter);locationFilter?.addEventListener('change',filter);filter()}
// Original profile sections become accessible disclosures.
const accordion=$('#accordion');if(accordion){const headings=$$('h3',accordion);headings.forEach((h,i)=>{const body=h.nextElementSibling;if(!body||body.tagName!=='DIV')return;const detail=document.createElement('details'),summary=document.createElement('summary');summary.textContent=h.textContent.trim();if(i===0)detail.open=true;if(/WORD FROM THE CHAIRMAN/i.test(summary.textContent))detail.id='chairman';h.before(detail);detail.append(summary,body);h.remove()});if(location.hash==='#chairman'){$('#chairman')?.setAttribute('open','');$('#chairman')?.scrollIntoView()}}
const legacyGalleryRedirect={'#downloads-tab':'download.html','#walkthrough-tab':'walkthroughs.html','#video-tab':'video-gallery.html','#photo-tab':'photo-gallery.html'};if(location.pathname.endsWith('/gallery.html')&&legacyGalleryRedirect[location.hash])location.replace(legacyGalleryRedirect[location.hash]);if(location.pathname.endsWith('/services.html')){if(location.hash==='#interior-tab')location.replace('interior-design.html');if(location.hash==='#after-tab')location.replace('after-sales.html')}
// Explicit email handoff, with a copyable fallback. No fake success or unsent lead.
const enquiry=$('#enquiry-form');if(enquiry){const project=new URLSearchParams(location.search).get('project');if(project){const option=$$('option',$('#enquiry-project')).find(o=>o.value.toLowerCase()===project.toLowerCase());if(option)$('#enquiry-project').value=option.value}enquiry.addEventListener('submit',e=>{e.preventDefault();if(!enquiry.reportValidity())return;const fd=new FormData(enquiry);const lines=['Jewel Homes enquiry','',...['name','email','mob','phone','project','city','state','country','address','organization','profession','comments'].filter(k=>fd.get(k)).map(k=>k.charAt(0).toUpperCase()+k.slice(1)+': '+fd.get(k))];const body=lines.join('\n');$('.email-draft').hidden=false;$('.email-draft textarea').value=body;$('.email-open').href='mailto:sales@jewelhomes.net?subject='+encodeURIComponent('Enquiry — '+(fd.get('project')||'Jewel Homes'))+'&body='+encodeURIComponent(body);$('.form-status').textContent='Your enquiry is prepared. Open your email app or copy the message below to send it to Jewel Homes.';$('.email-draft').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'})});$('.copy-enquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('.email-draft textarea').value);$('.form-status').textContent='Enquiry copied. Send it to sales@jewelhomes.net.'}catch{$('.email-draft textarea').select();$('.form-status').textContent='Select and copy the prepared message below.'}})}
const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);function emi(p,annual,n){const r=annual/1200;return r===0?p/n:p*r/(1-Math.pow(1+r,-n))}function validNumber(id){return Number($(id).value)}
const emiForm=$('#emi-form');if(emiForm){function calculate(){if(!emiForm.reportValidity())return;const principal=validNumber('#amount'),rate=validNumber('#rate'),months=validNumber('#years')*12,payment=emi(principal,rate,months),total=payment*months,interest=total-principal;$('#emi-result').textContent=currency(payment);$('#principal-result').textContent=currency(principal);$('#interest-result').textContent=currency(interest);$('#total-result').textContent=currency(total);$('#emi-donut').style.background=`conic-gradient(var(--gold) 0 ${principal/total*100}%,#58726c ${principal/total*100}% 100%)`}emiForm.addEventListener('submit',e=>{e.preventDefault();calculate()});calculate()}
const area=$('#area-value');if(area){function convert(){const n=Number(area.value),factor=Number($('#area-unit').value);$$('[data-area-factor]').forEach(el=>{const v=n*factor/Number(el.dataset.areaFactor);el.textContent=Number.isFinite(v)&&n>=0?new Intl.NumberFormat('en-IN',{maximumFractionDigits:6}).format(v):'—'})}area.addEventListener('input',convert);$('#area-unit').addEventListener('change',convert);convert()}
const loanForm=$('#loan-form');if(loanForm){function calculate(){if(!loanForm.reportValidity())return;const income=validNumber('#income')+validNumber('#coincome')-validNumber('#deductions')-validNumber('#otherloans'),capacity=Math.max(0,income*.4),perLakh=emi(100000,validNumber('#loanrate'),validNumber('#months'));$('#loan-result').textContent=currency(capacity/perLakh*100000);$('#capacity-result').textContent=currency(capacity);$('#per-lakh-result').textContent=currency(perLakh)}loanForm.addEventListener('submit',e=>{e.preventDefault();calculate()});calculate()}
// Source-based property explorer: no synthesized geometry or invented inventory.
if($('#explorer-select')){fetch('properties.json').then(r=>r.json()).then(properties=>{let p=properties.find(p=>p.prefix==='capital'&&p.category!=='Completed'),tab='overview',zoom=1,panX=0,panY=0,drag=null;const stage=$('#elevation-stage'),viewport=$('#explorer-viewport'),panel=$('#explorer-panel-content');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function transform(){stage.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`}function render(){const name=escape(p.name);$$('.explorer-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.explorerTab===tab));if(tab==='overview'){panel.innerHTML=`<p class="eyebrow">${escape(p.category)} RESIDENCE</p><h2>${escape(p.caption||p.name)}</h2>${p.facts.map(f=>`<div class="explorer-fact"><small>${escape(f.split(':')[0])}</small>${escape(f.split(':').slice(1).join(':').trim())}</div>`).join('')}<p style="margin-top:22px">${escape(p.paragraphs[0]||'Explore this Jewel Homes residence.')}</p>`}else if(tab==='plans'){panel.innerHTML=`<p class="eyebrow">ORIGINAL PROJECT PLANS</p><h2>Find your floor plan.</h2>`+(p.plans.length?`<div class="explorer-plans">${p.plans.map(pl=>`<a class="explorer-plan" href="${escape(pl.image)}" data-lightbox><img src="${escape(pl.thumb)}" alt="${escape(pl.label)}"><p>${escape(pl.label)}</p></a>`).join('')}</div>`:'<p>Floor plans are not published for this residence. Contact Jewel Homes to request them.</p>')}else{panel.innerHTML=`<p class="eyebrow">THE RESIDENCE</p><h2>Everyday amenities.</h2>`+(p.amenities.length?'<ul>'+p.amenities.map(a=>'<li>'+escape(a)+'</li>').join('')+'</ul>':'<p>Contact the Jewel Homes team for the full amenities and specifications of this residence.</p>')}$('#explorer-enquire').href='enquiry.html?project='+encodeURIComponent(p.name);$('#explorer-project-link').href=p.route;panel.scrollTop=0}
function choose(prefix){p=properties.find(q=>q.prefix===prefix&&q.category!=='Completed')||p;$('#explorer-select').value=p.prefix;$('#explorer-title').textContent=p.name;$('.explorer-elevation').src=p.image;$('.explorer-elevation').alt=p.name+' architectural elevation';zoom=1;panX=panY=0;transform();render()}
const requested=new URLSearchParams(location.search).get('project');choose(requested||'capital');$('#explorer-select').addEventListener('change',e=>{choose(e.target.value);history.replaceState(null,'','?project='+encodeURIComponent(p.prefix))});$$('[data-explorer-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.explorerTab;render();if(innerWidth<550&&b.classList.contains('hotspot'))$('.explorer-panel').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}));$('#zoom-in').addEventListener('click',()=>{zoom=Math.min(3,zoom+.25);transform()});$('#zoom-out').addEventListener('click',()=>{zoom=Math.max(1,zoom-.25);if(zoom===1)panX=panY=0;transform()});$('#zoom-reset').addEventListener('click',()=>{zoom=1;panX=panY=0;transform()});$('#viewer-fullscreen').addEventListener('click',()=>showImage(p.image,p.name+' — original Jewel Homes elevation',$('#viewer-fullscreen')));viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,px:panX,py:panY};viewport.setPointerCapture(e.pointerId)});viewport.addEventListener('pointermove',e=>{if(!drag)return;const maxX=viewport.clientWidth*.6,maxY=viewport.clientHeight*.6;panX=Math.max(-maxX,Math.min(maxX,drag.px+e.clientX-drag.x));panY=Math.max(-maxY,Math.min(maxY,drag.py+e.clientY-drag.y));transform()});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointercancel',()=>drag=null);
}).catch(()=>{$('#explorer-panel-content').innerHTML='<p>The explorer could not load. Please refresh or view the project collection.</p><a class="text-link" href="projects.html">View all residences ↗</a>'})}
})();
